if (richTextBox1.InvokeRequired)
            {
                richTextBox1.Invoke(new MethodInvoker(() => { SetLineTextColor(line, color); }));
            }
            else
            {
                int start = richTextBox1.GetFirstCharIndexFromLine(line);
